_DATASET_GZIP_BASE64 = ''


def load_embedded_dataset():
    raw = gzip.decompress(base64.b64decode(_DATASET_GZIP_BASE64))
    if hashlib.sha256(raw).hexdigest() != _DATASET_SHA256:
        raise ValueError("Dữ liệu phân tích không vượt qua kiểm tra toàn vẹn.")
    matrix = json.loads(raw.decode("utf-8"))
    return matrix[0], matrix[1], matrix[2:]


