NS_MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS_REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def _col_number(col_letters: str) -> int:
    n = 0
    for ch in col_letters:
        n = n * 26 + ord(ch) - 64
    return n


def read_xlsx_sheet(path: Path, sheet_name: str) -> List[List[object]]:
    with zipfile.ZipFile(path) as z:
        workbook = ET.fromstring(z.read("xl/workbook.xml"))
        relationships = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rel_map = {r.attrib["Id"]: r.attrib["Target"] for r in relationships}

        target = None
        for sheet in workbook.find(f"{{{NS_MAIN}}}sheets"):
            if sheet.attrib["name"] == sheet_name:
                rid = sheet.attrib[f"{{{NS_REL}}}id"]
                target = rel_map[rid].lstrip("/")
                if not target.startswith("xl/"):
                    target = "xl/" + target
                break
        if not target:
            raise KeyError(f"Không tìm thấy sheet '{sheet_name}' trong {path.name}")

        shared_strings: List[str] = []
        if "xl/sharedStrings.xml" in z.namelist():
            root = ET.fromstring(z.read("xl/sharedStrings.xml"))
            for si in root.findall(f"{{{NS_MAIN}}}si"):
                shared_strings.append(
                    "".join((t.text or "") for t in si.iter(f"{{{NS_MAIN}}}t"))
                )

        root = ET.fromstring(z.read(target))
        cells: Dict[Tuple[int, int], object] = {}
        max_row = max_col = 0

        for cell in root.iter(f"{{{NS_MAIN}}}c"):
            address = cell.attrib["r"]
            m = re.match(r"([A-Z]+)(\d+)", address)
            if not m:
                continue
            col_letters, row_text = m.groups()
            row = int(row_text)
            col = _col_number(col_letters)
            max_row = max(max_row, row)
            max_col = max(max_col, col)

            cell_type = cell.attrib.get("t")
            v = cell.find(f"{{{NS_MAIN}}}v")
            inline = cell.find(f"{{{NS_MAIN}}}is")

            if inline is not None:
                value = "".join(
                    (t.text or "") for t in inline.iter(f"{{{NS_MAIN}}}t")
                )
            elif v is None:
                value = None
            else:
                value = v.text
                if cell_type == "s":
                    value = shared_strings[int(value)]
                elif cell_type == "b":
                    value = bool(int(value))
                elif cell_type in (None, "n"):
                    try:
                        fv = float(value)
                        value = int(fv) if fv.is_integer() else fv
                    except Exception:
                        pass

            cells[(row, col)] = value

        return [
            [cells.get((r, c)) for c in range(1, max_col + 1)]
            for r in range(1, max_row + 1)
        ]


def discover_input_xlsx(explicit: str | None) -> Path:
    if explicit:
        p = Path(explicit).expanduser().resolve()
        if not p.exists():
            raise FileNotFoundError(f"Không tìm thấy file input: {p}")
        return p

    base = Path(__file__).resolve().parent
    candidates = [
        p for p in base.glob("*.xlsx")
        if "MBBank_Research_3Sheets_Professional" not in p.name
        and not p.name.startswith("~$")
    ]
    preferred = [
        p for p in candidates
        if "MB_Bank_FINAL_TFT_Optimized" in p.name
    ]
    if preferred:
        return sorted(preferred)[-1]
    if len(candidates) == 1:
        return candidates[0]
    raise FileNotFoundError(
        "Không tự xác định được workbook nguồn. "
        "Chạy: python script.py --input <file.xlsx>"
    )


