def normalize_raw(matrix: List[List[object]]):
    if len(matrix) < 3:
        raise ValueError("Sheet dữ liệu không đủ hàng.")

    headers = [str(x).strip() if x is not None else "" for x in matrix[0]]
    descriptions = [
        str(x).strip() if x is not None else "" for x in matrix[1]
    ]
    rows = [r[: len(headers)] for r in matrix[2:] if r and r[0] is not None]

    required = set(RAW_KEEP_COLUMNS)
    missing = required - set(headers)
    if missing:
        raise ValueError(f"Thiếu cột bắt buộc: {sorted(missing)}")
    return headers, descriptions, rows


def build_numeric_columns(headers, rows) -> Dict[str, np.ndarray]:
    idx = {h: i for i, h in enumerate(headers)}
    numeric = {}
    for h in headers:
        vals = []
        ok = True
        for row in rows:
            v = row[idx[h]]
            if v is None or v == "":
                ok = False
                break
            try:
                vals.append(float(v))
            except Exception:
                ok = False
                break
        if ok:
            numeric[h] = np.asarray(vals, dtype=float)
    return numeric


def validate_data(headers, rows, numeric):
    n = len(rows)
    if n != PROJECT_CONFIG["n_expected"]:
        raise ValueError(
            f"Số quan sát {n} khác n kỳ vọng {PROJECT_CONFIG['n_expected']}."
        )

    for construct, names in SCALE_ITEMS.items():
        for item in names:
            x = numeric[item]
            if np.any(
                (x < PROJECT_CONFIG["likert_min"])
                | (x > PROJECT_CONFIG["likert_max"])
            ):
                raise ValueError(f"{item} có giá trị ngoài thang 1–5.")


