def z(x):
    x = np.asarray(x, dtype=float)
    return (x - x.mean()) / x.std(ddof=0)


def cronbach_alpha(mat):
    mat = np.asarray(mat, dtype=float)
    q = mat.shape[1]
    return float(
        q / (q - 1)
        * (1 - mat.var(axis=0, ddof=1).sum() / mat.sum(axis=1).var(ddof=1))
    )


def citc(mat):
    mat = np.asarray(mat, dtype=float)
    vals = []
    for j in range(mat.shape[1]):
        vals.append(
            float(
                np.corrcoef(
                    mat[:, j],
                    np.delete(mat, j, axis=1).sum(axis=1),
                )[0, 1]
            )
        )
    return np.asarray(vals)


def alpha_if_deleted(mat):
    mat = np.asarray(mat, dtype=float)
    return np.asarray([
        cronbach_alpha(np.delete(mat, j, axis=1))
        for j in range(mat.shape[1])
    ])


def kmo_bartlett(mat):
    X = np.asarray(mat, dtype=float)
    C = np.corrcoef(X, rowvar=False)
    inv = np.linalg.pinv(C)

    P = np.zeros_like(C)
    for i in range(C.shape[0]):
        for j in range(C.shape[0]):
            if i != j:
                P[i, j] = -inv[i, j] / math.sqrt(inv[i, i] * inv[j, j])

    r2 = np.sum(C[np.triu_indices_from(C, 1)] ** 2)
    p2 = np.sum(P[np.triu_indices_from(P, 1)] ** 2)
    kmo = r2 / (r2 + p2)

    n, p = X.shape
    det = max(float(np.linalg.det(C)), 1e-12)
    chi = -(n - 1 - (2 * p + 5) / 6) * math.log(det)
    df = p * (p - 1) / 2
    pv = stats.chi2.sf(chi, df)
    return float(kmo), float(chi), int(df), float(pv)


def varimax(Phi, gamma=1.0, q=100, tol=1e-7):
    p, k = Phi.shape
    R = np.eye(k)
    d = 0.0

    for _ in range(q):
        old = d
        L = Phi @ R
        u, s, vh = np.linalg.svd(
            Phi.T @ (
                L ** 3
                - (gamma / p)
                * L @ np.diag(np.diag(L.T @ L))
            )
        )
        R = u @ vh
        d = float(s.sum())
        if old and d / old < 1 + tol:
            break
    return Phi @ R


def efa(mat, n_factors):
    X = StandardScaler().fit_transform(np.asarray(mat, dtype=float))
    C = np.corrcoef(X, rowvar=False)
    ev, evec = np.linalg.eigh(C)
    order = np.argsort(ev)[::-1]
    ev = ev[order]
    evec = evec[:, order]
    load = varimax(evec[:, :n_factors] * np.sqrt(ev[:n_factors]))
    return load, ev


def reorder_efa(loadings, block_names):
    """
    Mỗi block có 4 item. Đưa cột nhân tố về đúng thứ tự lý thuyết
    và đảo dấu để tải chính mang dấu dương.
    """
    L = np.asarray(loadings, dtype=float)
    used = set()
    order = []

    for block_idx, _ in enumerate(block_names):
        a = block_idx * 4
        b = a + 4
        mean_abs = np.mean(np.abs(L[a:b, :]), axis=0)
        candidates = np.argsort(mean_abs)[::-1]
        chosen = next(int(c) for c in candidates if int(c) not in used)
        used.add(chosen)
        order.append(chosen)

    L = L[:, order].copy()
    for j in range(len(block_names)):
        a = j * 4
        b = a + 4
        if L[a:b, j].mean() < 0:
            L[:, j] *= -1

    rotated_ss = (L ** 2).sum(axis=0)
    rotated_pct = rotated_ss / L.shape[0] * 100
    return L, rotated_ss, rotated_pct


def cr_ave(loads):
    l = np.asarray(loads, dtype=float)
    cr = (l.sum() ** 2) / ((l.sum() ** 2) + np.sum(1 - l ** 2))
    return float(cr), float(np.mean(l ** 2))


def htmt(blocks):
    names = list(blocks)
    out = np.eye(len(names))

    for a in range(len(names)):
        for b in range(a + 1, len(names)):
            A = blocks[names[a]]
            B = blocks[names[b]]

            C = np.corrcoef(A.T, B.T)
            hetero = np.mean(
                np.abs(C[: A.shape[1], A.shape[1] :])
            )

            ca = np.corrcoef(A, rowvar=False)
            cb = np.corrcoef(B, rowvar=False)

            mono_a = np.mean(
                np.abs(ca[np.triu_indices(A.shape[1], 1)])
            )
            mono_b = np.mean(
                np.abs(cb[np.triu_indices(B.shape[1], 1)])
            )

            out[a, b] = out[b, a] = (
                hetero / math.sqrt(mono_a * mono_b)
            )

    return names, out


def standardized_ols(y, X, names):
    Xz = np.column_stack([z(X[:, j]) for j in range(X.shape[1])])
    fit = sm.OLS(z(y), sm.add_constant(Xz)).fit()
    paths = {
        name: float(fit.params[i + 1])
        for i, name in enumerate(names)
    }
    return fit, paths


def vif_values(X, names):
    Xz = np.column_stack([z(X[:, j]) for j in range(X.shape[1])])
    return {
        name: float(variance_inflation_factor(Xz, i))
        for i, name in enumerate(names)
    }


def f2_drop(y, X, full_r2, idx):
    Xr = np.delete(X, idx, axis=1)
    r2r = LinearRegression().fit(Xr, y).score(Xr, y)
    return float((full_r2 - r2r) / (1 - full_r2))


def q2_cv_standardized(y, X, folds=10, seed=20260805):
    y = np.asarray(y, dtype=float)
    X = np.asarray(X, dtype=float)
    kf = KFold(folds, shuffle=True, random_state=seed)
    pred = np.zeros(len(y), dtype=float)

    for tr, te in kf.split(X):
        pred[te] = (
            LinearRegression()
            .fit(X[tr], y[tr])
            .predict(X[te])
        )

    q2 = 1 - np.sum((y - pred) ** 2) / np.sum((y - y.mean()) ** 2)
    rmse = np.sqrt(mean_squared_error(y, pred)) / y.std(ddof=1)
    return float(q2), float(rmse)


def regression_power(n, predictors=8, f2=0.02, alpha=0.05):
    df2 = n - predictors - 1
    if df2 <= 0:
        return 0.0
    critical = f_dist.ppf(1 - alpha, predictors, df2)
    return float(1 - ncf.cdf(critical, predictors, df2, f2 * n))


