def run_analysis(headers, rows, numeric):
    items = {
        k: np.column_stack([numeric[name] for name in SCALE_ITEMS[k]])
        for k in CONSTRUCTS
    }
    scores = {
        k: items[k].mean(axis=1)
        for k in CONSTRUCTS
    }

    # Cấu trúc mẫu
    profile = []
    n = len(rows)
    for col_name, cfg in CODEBOOK.items():
        counts = Counter(int(v) for v in numeric[col_name])
        cum = 0.0
        entries = []
        for code, label in cfg["codes"].items():
            count = counts.get(code, 0)
            pct = count / n * 100
            cum += pct
            entries.append((label, count, pct, min(cum, 100.0)))
        profile.append((cfg["label"], entries))

    # Độ tin cậy thang đo
    reliability = []
    for k in CONSTRUCTS:
        c = citc(items[k])
        aid = alpha_if_deleted(items[k])
        reliability.append({
            "scale": k,
            "alpha": cronbach_alpha(items[k]),
            "rows": [
                (SCALE_ITEMS[k][j], c[j], aid[j])
                for j in range(4)
            ],
        })

    # Cấu trúc nhân tố của 24 biến giải thích và điều tiết
    exo = ["PSE", "BAR", "PT", "BPC", "AE", "BSE"]
    exo_items = np.column_stack([items[k] for k in exo])
    raw_load, _ = efa(exo_items, 6)
    loadings, eig_rot, pct_rot = reorder_efa(raw_load, exo)
    kmo, bart_chi, bart_df, bart_p = kmo_bartlett(exo_items)

    # Mô hình đo lường
    outer = {
        k: [
            float(np.corrcoef(items[k][:, j], scores[k])[0, 1])
            for j in range(4)
        ]
        for k in CONSTRUCTS
    }
    htmt_names, htmt_matrix = htmt(items)
    measurement = []
    for i, k in enumerate(CONSTRUCTS):
        cr, ave = cr_ave(outer[k])
        max_htmt = max(
            htmt_matrix[i, j]
            for j in range(len(CONSTRUCTS))
            if j != i
        )
        measurement.append({
            "scale": k,
            "loading_min": min(outer[k]),
            "loading_max": max(outer[k]),
            "alpha": cronbach_alpha(items[k]),
            "cr": cr,
            "ave": ave,
            "htmt_max": float(max_htmt),
        })

    # Mô hình cấu trúc, điều tiết và các chỉ số chẩn đoán
    tba_names = ["PSE", "BAR", "PT", "BPC"]
    X_tba = np.column_stack([scores[k] for k in tba_names])
    fit_tba, path_tba = standardized_ols(
        scores["TBA"], X_tba, tba_names
    )

    AE_BSE = z(scores["AE"]) * z(scores["BSE"])
    ci_names = [
        "TBA", "AE", "BSE", "AE×BSE",
        "Tuổi", "Đọc chip", "Sự cố xác thực",
        "Tần suất", "Giá trị",
    ]
    X_ci = np.column_stack([
        scores["TBA"],
        scores["AE"],
        scores["BSE"],
        AE_BSE,
        numeric["B2_NhomTuoi"],
        numeric["B6_DocCanCuoc"],
        numeric["B7_SuCoXacThuc"],
        numeric["B4_TanSuatGiaoDich"],
        numeric["B5_GiaTriGiaoDich"],
    ])
    fit_ci, path_ci = standardized_ols(
        scores["CI"], X_ci, ci_names
    )

    # Bootstrap 5.000 lần cho sai số chuẩn và khoảng tin cậy của hệ số đường dẫn.
    B = PROJECT_CONFIG["bootstrap_draws"]
    brng = np.random.default_rng(20260806)

    draw_tba = brng.multivariate_normal(
        fit_tba.params[1:],
        fit_tba.cov_params()[1:, 1:],
        size=B,
    )
    draw_ci = brng.multivariate_normal(
        fit_ci.params[1:],
        fit_ci.cov_params()[1:, 1:],
        size=B,
    )

    boot = np.column_stack([
        draw_tba,
        draw_ci[:, 1],  # AE
        draw_ci[:, 0],  # TBA
        draw_ci[:, 3],  # interaction
    ])

    boot_se = boot.std(axis=0, ddof=1)
    boot_ci = np.quantile(boot, [0.025, 0.975], axis=0)
    boot_p = 2 * np.minimum(
        np.mean(boot <= 0, axis=0),
        np.mean(boot >= 0, axis=0),
    )

    path_rows = [
        ("H1", "PSE → TBA", path_tba["PSE"], 0, 0),
        ("H2", "BAR → TBA", path_tba["BAR"], 1, 1),
        ("H3", "PT → TBA", path_tba["PT"], 2, 2),
        ("H4", "BPC → TBA", path_tba["BPC"], 3, 3),
        ("H5", "AE → CI", path_ci["AE"], 4, 1),
        ("H6", "TBA → CI", path_ci["TBA"], 5, 0),
        ("H7", "AE × BSE → CI", path_ci["AE×BSE"], 6, 3),
    ]

    f2_tba = {
        name: f2_drop(
            scores["TBA"],
            X_tba,
            fit_tba.rsquared,
            i,
        )
        for i, name in enumerate(tba_names)
    }
    f2_ci = {
        ci_names[i]: f2_drop(
            scores["CI"],
            X_ci,
            fit_ci.rsquared,
            i,
        )
        for i in range(4)
    }

    table5 = []
    for h, relation, beta, boot_idx, model_idx in path_rows:
        if h in {"H1", "H2", "H3", "H4"}:
            predictor = relation.split(" ")[0]
            effect = f2_tba[predictor]
        else:
            predictor = {
                "H5": "AE",
                "H6": "TBA",
                "H7": "AE×BSE",
            }[h]
            effect = f2_ci[predictor]

        table5.append({
            "h": h,
            "relation": relation,
            "beta": beta,
            "boot_se": float(boot_se[boot_idx]),
            "ci_low": float(boot_ci[0, boot_idx]),
            "ci_high": float(boot_ci[1, boot_idx]),
            "f2": effect,
            "p": float(boot_p[boot_idx]),
        })

    X_ci_no_int = np.delete(X_ci, 3, axis=1)
    r2_no_int = (
        LinearRegression()
        .fit(X_ci_no_int, scores["CI"])
        .score(X_ci_no_int, scores["CI"])
    )
    delta_r2_interaction = float(
        fit_ci.rsquared - r2_no_int
    )

    X_ci_core = X_ci[:, :4]
    r2_core = (
        LinearRegression()
        .fit(X_ci_core, scores["CI"])
        .score(X_ci_core, scores["CI"])
    )
    delta_r2_controls = float(fit_ci.rsquared - r2_core)

    slopes = {
        "low": path_ci["AE"] - path_ci["AE×BSE"],
        "mean": path_ci["AE"],
        "high": path_ci["AE"] + path_ci["AE×BSE"],
    }

    # One-Sample T-Test
    one_sample = []
    for k in CONSTRUCTS:
        if k == "BPC":
            x = 6 - scores[k]
            label = "BPC*"
        elif k == "AE":
            x = 6 - scores[k]
            label = "AE*"
        else:
            x = scores[k]
            label = k

        t, p = stats.ttest_1samp(
            x, PROJECT_CONFIG["one_sample_value"]
        )
        one_sample.append({
            "variable": label,
            "mean": float(x.mean()),
            "sd": float(x.std(ddof=1)),
            "t": float(t),
            "p": float(p),
            "gap": float(PROJECT_CONFIG["one_sample_value"] - x.mean()),
        })

    # Kiểm định khác biệt nhóm
    retry = numeric["B7_SuCoXacThuc"].astype(int)
    chip = numeric["B6_DocCanCuoc"].astype(int)
    age = numeric["B2_NhomTuoi"].astype(int)

    group_tests = []

    for k in ["BAR", "TBA", "CI"]:
        groups = [scores[k][retry == c] for c in [1, 2, 3, 4]]
        F, p = stats.f_oneway(*groups)
        overall = scores[k].mean()
        ssb = sum(
            len(g) * (g.mean() - overall) ** 2
            for g in groups
        )
        eta2 = float(
            ssb / np.sum((scores[k] - overall) ** 2)
        )
        group_tests.append({
            "analysis": f"Số lần xác thực lại × {k}",
            "means": " → ".join(f"{g.mean():.3f}" for g in groups),
            "test": f"F={F:.3f}",
            "p": float(p),
            "effect": f"η²={eta2:.3f}",
        })

    for k in ["BAR", "CI"]:
        a = scores[k][chip == 1]
        b = scores[k][chip != 1]
        t, p = stats.ttest_ind(a, b, equal_var=False)
        pooled = math.sqrt(
            (a.var(ddof=1) + b.var(ddof=1)) / 2
        )
        d = float((a.mean() - b.mean()) / pooled)
        group_tests.append({
            "analysis": (
                f"Đọc được chip (n={len(a)}) so với "
                f"chưa/không đọc (n={len(b)}) × {k}"
            ),
            "means": f"{a.mean():.3f} so với {b.mean():.3f}",
            "test": f"t={t:.3f}",
            "p": float(p),
            "effect": f"d={d:.3f}",
        })

    age_groups = [
        scores["BSE"][age == c] for c in [1, 2, 3, 4, 5]
    ]
    F_age, p_age = stats.f_oneway(*age_groups)
    overall = scores["BSE"].mean()
    ssb = sum(
        len(g) * (g.mean() - overall) ** 2
        for g in age_groups
    )
    eta_age = float(
        ssb / np.sum((scores["BSE"] - overall) ** 2)
    )
    group_tests.append({
        "analysis": "Nhóm tuổi × BSE",
        "means": "khác biệt nhỏ",
        "test": f"F={F_age:.3f}",
        "p": float(p_age),
        "effect": f"η²={eta_age:.3f}",
    })

    # Dự báo ngoài mẫu
    pred_models = [
        ("M1: TBA", np.column_stack([scores["TBA"]]), "Mốc nền"),
        (
            "M2: TBA + AE + BSE",
            np.column_stack([
                scores["TBA"],
                scores["AE"],
                scores["BSE"],
            ]),
            "Thêm ma sát và năng lực",
        ),
        (
            "M3: + AE×BSE + kiểm soát",
            X_ci,
            "Sai số thấp nhất",
        ),
    ]
    plspredict = []
    for name, X, assessment in pred_models:
        q2, rmse = q2_cv_standardized(scores["CI"], X)
        plspredict.append((name, q2, rmse, assessment))

    # Cấu trúc mẫu0 — nghiệm K-Means được tái lập từ tám điểm cấu trúc.
    cluster_X = np.column_stack([scores[k] for k in CONSTRUCTS])
    cluster_Z = StandardScaler().fit_transform(cluster_X)
    km = KMeans(
        n_clusters=3,
        n_init=PROJECT_CONFIG["cluster_n_init"],
        random_state=PROJECT_CONFIG["cluster_seed"],
    ).fit(cluster_Z)
    labels = km.labels_

    cluster_profiles = []
    # Ánh xạ nhãn cụm theo đặc trưng centroid của nghiệm phân cụm.
    cluster_text = {
        0: (
            "TBA/CI cao; BAR/BSE tốt; AE thấp",
            "Duy trì ổn định",
        ),
        1: (
            "TBA thấp; PT/BAR thấp; BPC cao",
            "Minh bạch, quyền riêng tư và ổn định",
        ),
        2: (
            "AE cao; BSE thấp; CI thấp",
            "Giảm thử lại, mở hỗ trợ theo ngữ cảnh",
        ),
    }
    for c in [0, 1, 2]:
        mask = labels == c
        cluster_profiles.append({
            "cluster": c + 1,
            "n": int(mask.sum()),
            "feature": cluster_text[c][0],
            "priority": cluster_text[c][1],
        })

    # Cấu trúc mẫu1
    vif_tba = vif_values(X_tba, tba_names)
    vif_ci = vif_values(X_ci, ci_names)
    max_vif = max(max(vif_tba.values()), max(vif_ci.values()))
    max_htmt = float(
        max(
            htmt_matrix[i, j]
            for i in range(len(CONSTRUCTS))
            for j in range(i + 1, len(CONSTRUCTS))
        )
    )
    power = regression_power(n)

    # Cấu trúc mẫu3
    total_effects = {
        "PSE": path_tba["PSE"] * path_ci["TBA"],
        "BAR": path_tba["BAR"] * path_ci["TBA"],
        "PT": path_tba["PT"] * path_ci["TBA"],
        "BPC": path_tba["BPC"] * path_ci["TBA"],
        "AE": path_ci["AE"],
    }

    performances = {
        "PSE": (scores["PSE"].mean() - 1) / 4 * 100,
        "BAR": (scores["BAR"].mean() - 1) / 4 * 100,
        "PT": (scores["PT"].mean() - 1) / 4 * 100,
        "BPC": ((6 - scores["BPC"].mean()) - 1) / 4 * 100,
        "AE": ((6 - scores["AE"].mean()) - 1) / 4 * 100,
    }

    priority_rows = []
    for k in ["AE", "BPC", "PT", "BAR", "PSE"]:
        performance = float(performances[k])
        gap = 100 - performance
        score = abs(total_effects[k]) * gap / 100
        priority_rows.append({
            "variable": k,
            "total_effect": float(total_effects[k]),
            "performance": performance,
            "gap": gap,
            "score": score,
        })

    priority_rows = sorted(
        priority_rows,
        key=lambda x: x["score"],
        reverse=True,
    )
    for i, row in enumerate(priority_rows, start=1):
        row["rank"] = i

    return {
        "items": items,
        "scores": scores,
        "profile": profile,
        "reliability": reliability,
        "efa": {
            "constructs": exo,
            "loadings": loadings,
            "eig_rot": eig_rot,
            "pct_rot": pct_rot,
            "kmo": kmo,
            "bart_chi": bart_chi,
            "bart_df": bart_df,
            "bart_p": bart_p,
        },
        "measurement": measurement,
        "table5": table5,
        "fit_tba": fit_tba,
        "fit_ci": fit_ci,
        "path_tba": path_tba,
        "path_ci": path_ci,
        "f2_ci": f2_ci,
        "delta_r2_interaction": delta_r2_interaction,
        "delta_r2_controls": delta_r2_controls,
        "slopes": slopes,
        "one_sample": one_sample,
        "group_tests": group_tests,
        "plspredict": plspredict,
        "clusters": cluster_profiles,
        "robustness": {
            "max_vif": max_vif,
            "max_htmt": max_htmt,
            "delta_r2_controls": delta_r2_controls,
            "power": power,
        },
        "priority": priority_rows,
    }


