NAVY = "#1F4E78"
NAVY_DARK = "#17365D"
LIGHT_BLUE = "#D9EAF7"
HEADER_GRAY = "#E7E6E6"
GRID = "#A6A6A6"
TEXT = "#1F1F1F"
MUTED = "#666666"
RED = "#C00000"
WHITE = "#FFFFFF"

FONT_BODY = {"name": "Times New Roman", "size": 13, "color": TEXT}
FONT_RAW = {"name": "Times New Roman", "size": 10, "color": TEXT}
FONT_TITLE = {"name": "Times New Roman", "size": 16, "bold": True, "color": WHITE}
FONT_SUBTITLE = {"name": "Times New Roman", "size": 13, "italic": True, "color": MUTED}
FONT_SECTION = {"name": "Times New Roman", "size": 13, "bold": True, "color": NAVY_DARK}
FONT_HEADER = {"name": "Times New Roman", "size": 13, "bold": True, "color": TEXT}
FONT_KEY = {"name": "Times New Roman", "size": 13, "bold": True, "color": RED}

BORDER_ALL = {"preset": "all", "style": "thin", "color": GRID}


def p_text(p: float) -> str:
    return "<0,001" if p < 0.001 else f"{p:.3f}".replace(".", ",")


def ci_text(lo, hi):
    return (
        f"[{lo:.3f}; {hi:.3f}]"
        .replace(".", ",")
    )


def style_table(sheet, start_row, end_row, start_col, end_col, header_row=None):
    rng = sheet.get_range(
        f"{start_col}{start_row}:{end_col}{end_row}"
    )
    rng.format.font = FONT_BODY
    rng.format.borders = BORDER_ALL
    rng.format.vertical_alignment = "center"

    if header_row is not None:
        hdr = sheet.get_range(
            f"{start_col}{header_row}:{end_col}{header_row}"
        )
        hdr.format.fill = HEADER_GRAY
        hdr.format.font = FONT_HEADER
        hdr.format.wrap_text = True
        hdr.format.row_height = 29


def section_title(sheet, row, text, end_col="I"):
    sheet.merge_cells(f"A{row}:{end_col}{row}")
    rng = sheet.get_range(f"A{row}:{end_col}{row}")
    rng.values = [[text]]
    rng.format.fill = LIGHT_BLUE
    rng.format.font = FONT_SECTION
    rng.format.row_height = 24
    rng.format.vertical_alignment = "center"
    return row + 1


def caption(sheet, row, text, end_col="I"):
    sheet.merge_cells(f"A{row}:{end_col}{row}")
    rng = sheet.get_range(f"A{row}:{end_col}{row}")
    rng.values = [[text]]
    rng.format.font = {
        "name": "Times New Roman",
        "size": 13,
        "bold": True,
        "color": TEXT,
    }
    rng.format.row_height = 22
    return row + 1


def source_note(sheet, row, text, end_col="I"):
    sheet.merge_cells(f"A{row}:{end_col}{row}")
    rng = sheet.get_range(f"A{row}:{end_col}{row}")
    rng.values = [[text]]
    rng.format.font = {
        "name": "Times New Roman",
        "size": 11,
        "italic": True,
        "color": MUTED,
    }
    rng.format.row_height = 18
    return row + 1


