# ===========================================================================
# 8. THỰC THI PHÂN TÍCH
# ===========================================================================

def main():
    parser = argparse.ArgumentParser(
        description="Phân tích dữ liệu nghiên cứu xác thực sinh trắc học MBBank."
    )
    parser.add_argument(
        "--input",
        help="Đường dẫn tệp dữ liệu nghiên cứu (.xlsx).",
    )
    parser.add_argument(
        "--output",
        help="Đường dẫn tệp kết quả (.xlsx).",
    )
    args = parser.parse_args()

    if args.input:
        input_path = Path(args.input).expanduser().resolve()
        matrix = read_xlsx_sheet(input_path, PROJECT_CONFIG["source_sheet"])
        headers, descriptions, rows = normalize_raw(matrix)
    else:
        input_path = None
        headers, descriptions, rows = load_embedded_dataset()

    output_path = (
        Path(args.output).expanduser().resolve()
        if args.output
        else Path(__file__).resolve().with_name("MB BANK kết quả(2).xlsx")
    )

    numeric = build_numeric_columns(headers, rows)
    validate_data(headers, rows, numeric)
    analysis = run_analysis(headers, rows, numeric)

    build_workbook(
        headers,
        descriptions,
        rows,
        numeric,
        analysis,
        output_path,
    )

    print("Hoàn tất.")
    if input_path is not None:
        print(f"Dữ liệu : {input_path}")
    print(f"Kết quả : {output_path}")
    print(f"n = {len(rows)}")
    print(
        "R² TBA = "
        f"{analysis['fit_tba'].rsquared:.3f} | "
        "R² CI = "
        f"{analysis['fit_ci'].rsquared:.3f}"
    )
    print(
        "Beta PSE→TBA = "
        f"{analysis['path_tba']['PSE']:.3f} | "
        "Beta TBA→CI = "
        f"{analysis['path_ci']['TBA']:.3f} | "
        "Beta AE×BSE→CI = "
        f"{analysis['path_ci']['AE×BSE']:.3f}"
    )
    print(
        "K-Means counts = "
        + ", ".join(
            f"C{x['cluster']}={x['n']}"
            for x in analysis["clusters"]
        )
    )


if __name__ == "__main__":
    main()
